const inp = $workflow.input || {};
const src = inp.requestSource || 'InjurySeverityLookup';
const scenario = inp.scenario || 'Standard';
const incidentLocation = inp.incidentLocation || '';

const SCENARIOS = {
  Standard: { notificationDelayDays: 0, estimatedQuantum: 345000, litigationRiskBand: 'Low', deteriorationRiskBand: 'Low', employmentStatus: 'Employed - full time' },
  Displaced: { notificationDelayDays: 0, estimatedQuantum: 400000, litigationRiskBand: 'Low', deteriorationRiskBand: 'Medium', employmentStatus: 'Employed - full time' },
  Underinsured: { notificationDelayDays: 0, estimatedQuantum: 340000, litigationRiskBand: 'Low', deteriorationRiskBand: 'Low', employmentStatus: 'Employed - full time' },
  Investigated: { notificationDelayDays: 0, estimatedQuantum: 270000, litigationRiskBand: 'Low', deteriorationRiskBand: 'Low', employmentStatus: 'Employed - full time' },
  Declined: { notificationDelayDays: 75, estimatedQuantum: 295000, litigationRiskBand: 'High', deteriorationRiskBand: 'Low', employmentStatus: 'Signed off work' },
  Reopened: { notificationDelayDays: 0, estimatedQuantum: 315000, litigationRiskBand: 'Low', deteriorationRiskBand: 'Medium', employmentStatus: 'Employed - full time' }
};

const s = SCENARIOS[scenario] || SCENARIOS.Standard;

const out = {
  notificationDelayDays: 0,
  estimatedQuantum: 0,
  litigationRiskBand: '',
  deteriorationRiskBand: '',
  employmentStatus: '',
  explanation: ''
};

if (src === 'InjurySeverityLookup') {
  out.notificationDelayDays = s.notificationDelayDays;
  out.estimatedQuantum = s.estimatedQuantum;
  out.litigationRiskBand = s.litigationRiskBand;
  out.deteriorationRiskBand = s.deteriorationRiskBand;
  out.employmentStatus = s.employmentStatus;
  out.explanation = 'Severity assessment for ' + (incidentLocation || 'the incident location') + ' returned an estimated quantum of ' + s.estimatedQuantum + ' with ' + s.litigationRiskBand + ' litigation risk and ' + s.notificationDelayDays + ' vacancy days.';
} else {
  out.explanation = 'Unrecognised requestSource: ' + src + '.';
}

return out;
